package com.example.TuVanSinhVien.controller;

import com.example.TuVanSinhVien.config.CustomUserDetails;
import com.example.TuVanSinhVien.entity.TaiKhoan;
import com.example.TuVanSinhVien.repository.TaiKhoanRepository;
import com.example.TuVanSinhVien.service.CatalogService;
import com.example.TuVanSinhVien.service.ContentService;
import com.example.TuVanSinhVien.service.ReportService;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
@RequestMapping("/admin")
public class AdminController {
    private final ReportService reportService;
    private final TaiKhoanRepository taiKhoanRepo;
    private final CatalogService catalogService;
    private final ContentService contentService;
    private final PasswordEncoder passwordEncoder;

    @GetMapping("/dashboard")
    public String dashboard(Model model) {
        model.addAttribute("summary", reportService.getDashboardSummary());
        return "admin/dashboard";
    }

    @GetMapping("/users")
    public String users(@RequestParam(required = false) String role, Model model) {
        if (role != null && !role.isEmpty()) {
            model.addAttribute("users", taiKhoanRepo.findByVaiTro(role));
        } else {
            model.addAttribute("users", taiKhoanRepo.findAll());
        }
        model.addAttribute("selectedRole", role);
        return "admin/users";
    }

    @PostMapping("/users/{id}/toggle-status")
    public String toggleUserStatus(@PathVariable Integer id, RedirectAttributes redirectAttributes) {
        taiKhoanRepo.findById(id).ifPresent(u -> {
            if ("HoatDong".equals(u.getTrangThai())) {
                u.setTrangThai("Khoa");
            } else {
                u.setTrangThai("HoatDong");
            }
            taiKhoanRepo.save(u);
            redirectAttributes.addFlashAttribute("successMessage", "Cập nhật trạng thái tài khoản #" + id + " thành công!");
        });
        return "redirect:/admin/users";
    }

    @PostMapping("/users/{id}/reset-password")
    public String resetPassword(@PathVariable Integer id, RedirectAttributes redirectAttributes) {
        taiKhoanRepo.findById(id).ifPresent(u -> {
            u.setMatKhau(passwordEncoder.encode("123456"));
            u.setBatBuocDoiMatKhau(true);
            taiKhoanRepo.save(u);
            redirectAttributes.addFlashAttribute("successMessage", "Đã đặt lại mật khẩu cho tài khoản \'" + u.getTenDangNhap() + "\' thành \'123456\'.");
        });
        return "redirect:/admin/users";
    }

    @GetMapping("/catalogs")
    public String catalogs(Model model) {
        model.addAttribute("donViList", catalogService.getAllDonVi());
        model.addAttribute("linhVucList", catalogService.getAllLinhVuc());
        return "admin/catalogs";
    }

    @GetMapping("/content")
    public String content(Model model) {
        model.addAttribute("faqs", contentService.getAllFaqs());
        model.addAttribute("articles", contentService.getAllArticles());
        return "admin/content";
    }

    @PostMapping("/content/faq/{id}/approve")
    public String approveFaq(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, RedirectAttributes redirectAttributes) {
        TaiKhoan admin = taiKhoanRepo.findById(userDetails.getMaTK()).orElse(null);
        contentService.approveFaq(id, admin);
        redirectAttributes.addFlashAttribute("successMessage", "Đã duyệt và công khai câu hỏi FAQ #" + id);
        return "redirect:/admin/content";
    }

    @PostMapping("/content/article/{id}/approve")
    public String approveArticle(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, RedirectAttributes redirectAttributes) {
        TaiKhoan admin = taiKhoanRepo.findById(userDetails.getMaTK()).orElse(null);
        contentService.approveArticle(id, admin);
        redirectAttributes.addFlashAttribute("successMessage", "Đã xuất bản bài viết hướng dẫn #" + id);
        return "redirect:/admin/content";
    }

    @java.lang.SuppressWarnings("all")
    @lombok.Generated
    public AdminController(final ReportService reportService, final TaiKhoanRepository taiKhoanRepo, final CatalogService catalogService, final ContentService contentService, final PasswordEncoder passwordEncoder) {
        this.reportService = reportService;
        this.taiKhoanRepo = taiKhoanRepo;
        this.catalogService = catalogService;
        this.contentService = contentService;
        this.passwordEncoder = passwordEncoder;
    }
}
